    const pit = s.pit.filter((p) => AIR(at(p)));
    if (pit.length) add("6 sealed", "the envelope's floor (under y -4) is open", pit);
    const pitSpawn = s.pit.filter((p) => !AIR(at(p)) && !SPAWNPROOF.test(at(p)));
    if (pitSpawn.length && !light) add("8 lit or unspawnable", "the empty envelope's floor is a full block a mob can spawn on (use glass or slabs, or light it)", pitSpawn);
    const fasciaOpen = s.fascia.filter((p) => AIR(at(p)));
    if (fasciaOpen.length) add("6 sealed", "the header (y 4 up) is open to the street: close it in front with a fascia or sign board", fasciaOpen);
    const blocked = s.front.filter((p) => !AIR(at(p)) && !/sign|banner|_slab$|carpet/.test(at(p)));
    if (blocked.length) add("3 street", "the 2 cells in front of the counter must stay clear from y 1 to 3 (customers, payout, horses, stairs)", blocked);
    const wet = [...s.pit, ...s.backWall.filter((p) => p[1] < layout.floorY)].filter((p) => /water|bubble/.test(at(p)));
    if (wet.length) add("9 dry", "water at the envelope below grade", wet);
    if (light) {
      const dark = [...s.service, ...s.front.filter((p) => p[1] === layout.floorY + 1)].filter((p) => AIR(at(p)) && light(...p) < 1);
      if (dark.length) add("8 lit or unspawnable", `${dark.length} dark cells next to the envelope`, dark);
    }
    if (reached) {
      // the keeper's way in is the designer's call: a service aisle behind (back-to-back rows) or a hatch from a staff
      // floor above (a trapdoor in the floor over the socket, at y 7 or 8, with a reachable cell over it)
      // level with the shop floor or a step down into the aisle (both shop runs' engineers sank theirs a block)
      const svc = s.service.some(([x, y, z]) => reached(x, y, z) || reached(x, y - 1, z));
      const hatch = boxCells(s).filter((p) => p[1] === layout.floorY).some(([x, , z]) => [FLOOR_ABOVE, FLOOR_ABOVE + 1].some((v) => {
        const y = layout.floorY + v;
        return /trapdoor/.test(at([x, y, z])) && (reached(x, y + 1, z) || reached(x, y, z));
      }));
      if (!svc && !hatch) add("keeper", "the keeper can't reach this socket: give it a service aisle behind its back wall, or a hatch (trapdoor) in the staff floor over it, on a route customers can't take", s.service);
    }
    if (!layout.display?.[s.id]) add("show", "no product on show: the machine's counter and header would show the bench's spruce goods; set this shop's display in sockets.json (\"display\": { \"" + s.id + "\": \"bookshelf\" })", s.counter);
    out.push({ id: s.id, kind: s.kind, takes: s.takes, problems: P });
    all.push(...P.map((x) => ({ socket: s.id, ...x })));
  }
